import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import '../../../core/errors/app_error.dart';
import '../../auth/presentation/auth_scope.dart';
import '../../location/data/location_repository.dart';
import '../../location/domain/location_models.dart';
import '../data/reporter_economy_repository.dart';
import '../domain/reporter_economy.dart';
class ReporterLeaderboardScreen extends StatefulWidget{const ReporterLeaderboardScreen({super.key});@override State<ReporterLeaderboardScreen> createState()=>_LeaderboardState();}
class _LeaderboardState extends State<ReporterLeaderboardScreen>{ReporterEconomyRepository? repo;LocationRepository? locations;List<ReporterStats> rows=[];List<LocationRow> countries=[],cities=[];String country='',city='';int? days=30;bool loading=true;String? error;
 @override void didChangeDependencies(){super.didChangeDependencies();if(repo!=null)return;final c=AuthScope.read(context).service.client;if(c==null){loading=false;error='Supabase is not configured.';}else{repo=ReporterEconomyRepository(c);locations=LocationRepository(c);start();}}
 Future<void> start()async{try{countries=await locations!.countries();await load();}catch(e){if(mounted)setState((){error=AppError.message(e);loading=false;});}}
 Future<void> load()async{setState((){loading=true;error=null;});try{final x=await repo!.leaderboard(countryId:country.isEmpty?null:country,cityId:city.isEmpty?null:city,days:days);if(mounted)setState(()=>rows=x);}catch(e){if(mounted)setState(()=>error=AppError.message(e));}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> countryChanged(String? v)async{country=v??'';city='';cities=country.isEmpty?[]:await locations!.cities(countryId:country);if(mounted){setState((){});load();}}
 @override Widget build(BuildContext context)=>SafeArea(child:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,20,16,80),children:[Text('Top reporters',style:Theme.of(context).textTheme.headlineMedium),const Text('Ranked by trust, rating and points.'),Wrap(spacing:10,children:[DropdownButton<int?>(value:days,items:const[DropdownMenuItem(value:7,child:Text('7 days')),DropdownMenuItem(value:30,child:Text('30 days')),DropdownMenuItem(value:null,child:Text('All time'))],onChanged:(v){days=v;load();}),DropdownButton<String>(value:country,items:[const DropdownMenuItem(value:'',child:Text('All countries')),...countries.map((x)=>DropdownMenuItem(value:x.id,child:Text(x.name)))],onChanged:countryChanged),if(country.isNotEmpty)DropdownButton<String>(value:city,items:[const DropdownMenuItem(value:'',child:Text('All cities')),...cities.map((x)=>DropdownMenuItem(value:x.id,child:Text(x.name)))],onChanged:(v){city=v??'';load();})]),if(error!=null)Card(child:Padding(padding:const EdgeInsets.all(12),child:Text(error!))),if(loading)const Padding(padding:EdgeInsets.all(40),child:Center(child:CircularProgressIndicator()))else if(rows.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Text('No ranked reporters for this filter.'))else ...rows.map((x)=>Card(child:ListTile(onTap:x.username.isEmpty?null:()=>context.go('/reporter/${Uri.encodeComponent(x.username)}'),leading:CircleAvatar(child:Text('${x.rank??'-'}')),title:Text(x.name.isEmpty?'@${x.username}':x.name),subtitle:Text('@${x.username} • ${x.published} published • ${x.followers} followers'),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.end,children:[Text('${x.points} pts'),Text('★ ${x.rating} • ${x.trust}')]))))])));}
